                'namespace': 'legacy',
                'monthly_cost': 45.23
            }
        ]

# 使用示例
if __name__ == "__main__":
    analyzer = CostAnalyzer("http://prometheus:9090")

    end_time = datetime.now()
    start_time = end_time - timedelta(days=30)

    report = analyzer.generate_cost_report(start_time, end_time)

